import {KEYS,RANKS,OFFICES,ACTIVITIES,create,age,career,event,advance,decide,validate} from './engine.js';
import {playHint,stop} from './audio.js';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,activity=0,speed=1,allocation=[20,20,20,20,20];const STORAGE='qingyun-save-v1';
try{const saved=localStorage.getItem(STORAGE);if(saved)state=validate(JSON.parse(saved));}catch{toast('本地存档无法读取，可以导入备份或开始新人生。');}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500);}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{toast('自动保存失败，请导出存档备份。');}}
function modal(html){$('#modal').innerHTML=html+'<div class="divider"></div><button id="close-dialog" class="primary">继续旅程</button>';$('#modal').showModal();$('#close-dialog').onclick=()=>$('#modal').close();}
$('#help').onclick=()=>modal(`<span class="eyebrow">HOW TO PLAY</span><h2>把一生，过成自己的答案。</h2><p>从出生开始，每天选择一项活动。体是物质基础，劳是根本实践途径，德统领方向，智提供能力，美丰富精神。所有活动都能联动促进五维成长。</p><p>日 / 周 / 月 / 年分别获得100% / 85% / 68% / 50%的观察与履历收益；五维成长照常逐日结算。快进会在每个生日暂停，等待年度抉择。</p><p>22岁开始任职。晋升主要取决于年龄与历年决策；五维影响履历积累，逐日观察可减轻错误决策的延误。每年全选正确，可在寿命80%时到达国家主席。默认90岁寿命，目标72岁。</p><p>金手指「闻弦知意」：点击选项旁的试听，激昂明亮暗示正确，低沉悲伤暗示错误。第一版使用随机转调的程序配乐，预留授权音乐库。</p><p>参考中国综合管理类12职级、10层领导职务和27至1级数字级别，三者分开展示；晋升节奏、人物与制度均为虚构游戏规则。<a href="https://www.gov.cn/xinwen/2019-03/27/content_5377422.htm" target="_blank" rel="noreferrer">职级参考来源 ↗</a></p><p>存档仅保存在当前浏览器，可导出备份。此版为单机原型，未加入在线排行榜与反作弊。</p>`);
function setup(){ $('#app').innerHTML=`<div class="intro"><section class="intro-copy"><span class="eyebrow">一生向上 · 每一天都有回响</span><h1>青云之路，<br>始于平凡一日。</h1><p>在澄川，从第一次认识世界，到为一个国家承担责任。用德、智、体、美、劳，写下属于你的人生纪事。</p><div class="divider"></div><div class="row sub"><span>01 / 出生与成长</span><span>02 / 抉择与担当</span><span>03 / 青云之巅</span></div><div class="landscape" aria-hidden="true"><div class="mountain"></div><div class="mountain"></div></div></section><section class="card"><div class="row"><h2>开启一段人生</h2><button id="random" class="smallbtn">↻ 随机角色</button></div><div class="form-grid"><label>角色姓名<input type="text" id="name" maxlength="20" value="林知远"></label><label>预期寿命 · 岁<input type="number" id="life" min="70" max="110" value="90"></label></div><div class="divider"></div><div class="row"><h3>五维禀赋</h3><span class="sub">自由分配 · 总点数 <b id="total">100</b> / 100</span></div><div id="alloc">${KEYS.map((k,i)=>`<div class="stat-input"><label for="stat${i}">${k}</label><input type="range" min="5" max="60" value="20" id="stat${i}" data-stat="${i}"><output id="out${i}">20</output></div>`).join('')}</div><p class="sub">五者相互成就。起点不同，总禀赋相同。</p><div class="divider"></div><label for="skill">选择金手指</label><select id="skill"><option>♫ 闻弦知意 · 聆听抉择的 BGM</option></select><p class="sub">命运不说话，但它有自己的旋律。</p><p class="error" id="error" role="alert"></p><button class="primary advance" id="begin">落笔人生 →</button><button id="import-start" class="advance">导入已有存档</button></section></div>`;
document.querySelectorAll('[data-stat]').forEach(el=>el.oninput=()=>{allocation[+el.dataset.stat]=+el.value;$('#out'+el.dataset.stat).value=el.value;$('#total').textContent=allocation.reduce((a,b)=>a+b,0);});$('#random').onclick=()=>{allocation=[5,5,5,5,5];for(let n=0;n<75;n++){let i=Math.floor(Math.random()*5);while(allocation[i]>=60)i=(i+1)%5;allocation[i]++;}allocation.forEach((x,i)=>{$('#stat'+i).value=x;$('#out'+i).value=x;});$('#total').textContent=100;$('#name').value=['林知远','沈清禾','陆行舟','许明川','苏望舒'][Math.floor(Math.random()*5)];};$('#begin').onclick=()=>{try{state=create($('#name').value,allocation,+$('#life').value);save();render();}catch(e){$('#error').textContent=e.message;}};$('#import-start').onclick=importSave;}
function render(){if(!state)return setup();const c=career(state),a=age(state),e=state.pending?event(state):null;$('#app').innerHTML=`<div class="title-row"><div><span class="eyebrow">YOUR LIFE, YOUR CHAPTER</span><h1>人生纪事 <span class="gold">·</span> ${a<6?'初识世界':a<18?'求知时光':a<22?'蓄势待发':c.progress>=1?'山河在肩':'躬身入局'}</h1></div><div class="tools"><button id="export" class="smallbtn">导出存档</button><button id="import" class="smallbtn">导入</button><button id="reset" class="smallbtn">新的人生</button></div></div>${state.ended?`<div class="ended"><span class="eyebrow">THE FINAL CHAPTER</span><h2>${c.progress>=1?'青云之巅，山河有记。':'一生走过，亦有回响。'}</h2><p>享年 ${a} 岁 · ${esc(c.office)} · 正确抉择 ${state.correct} 次</p></div>`:''}<div class="grid"><aside><section class="card profile"><div class="portrait">${esc(state.name.slice(0,1))}</div><h2>${esc(state.name)}</h2><span class="sub">澄川公民 · ${a}岁 ${state.day%365}天</span><div><span class="badge">${esc(c.rank)}</span></div><div class="metric"><div><b>${Math.floor(state.merit).toLocaleString()}</b><span class="sub">履历积累</span></div><div><b>${state.correct}/${state.decisions}</b><span class="sub">正确抉择</span></div></div><div class="divider"></div>${KEYS.map((k,i)=>`<div class="attribute"><div class="row"><span>${k} <small class="sub">${['方向','能力','基础','精神','实践'][i]}</small></span><b>${state.stats[i].toFixed(1)}</b></div><div class="bar"><i style="width:${state.stats[i]}%"></i></div></div>`).join('')}<p class="quote">以体为基，以劳为径。<br>以德为向，以智为翼，以美润心。</p></section></aside><section><div class="hero card"><span class="eyebrow">${a<22?'成长篇章':'当前领导职务'}</span><h2>${esc(c.office)}</h2><p>${a<22?'成长从不只有一个方向。认真对待今天，就是给未来最好的答复。':'从一件具体的小事开始，让每一份担当都有真实的分量。'}</p><div class="row sub" style="color:#c4d4c4"><span>人生进程 ${Math.floor(state.day/(state.lifespan*365)*100)}%</span><span>数字级别 ${c.level}${a>=22?'级':''}</span></div><div class="bar"><i style="width:${state.day/(state.lifespan*365)*100}%"></i></div></div>${e?`<div class="card section event-card"><span class="event-tag">第 ${a} 年 · 关键抉择</span><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p><div class="choices">${e.options.map((o,i)=>`<div class="choice"><button data-choice="${i}">${'ABC'[i]} · ${esc(o)}</button><button class="listen" data-listen="${i}" aria-label="试听选项${'ABC'[i]}的背景音乐">♫ 试听 BGM</button></div>`).join('')}</div><p class="sub">闻弦知意：戴上耳机，听见命运的暗示。年度抉择不会被快进跳过。</p><button id="stop" class="smallbtn">停止音乐</button></div>`:`<section class="section"><div class="section-head"><h2>今日修行</h2><span class="sub">一项活动 · 五维共生</span></div><div class="actions">${ACTIVITIES.map((x,i)=>`<button title="${x.desc}" class="activity ${i===activity?'selected':''}" data-activity="${i}" ${state.ended?'disabled':''}><b>${x.icon}</b>${x.name}</button>`).join('')}</div><p class="sub" id="activity-desc">${ACTIVITIES[activity].desc}</p><div class="card"><div class="section-head"><h3>时光的步幅</h3><span class="sub">观察收益 ${speed===1?'100':speed===7?'85':speed===30?'68':'50'}%</span></div><div class="speed">${[1,7,30,365].map((n,i)=>`<button data-speed="${n}" class="${speed===n?'selected':''}" ${state.ended?'disabled':''}>${['一天','一周','一月','一年'][i]}</button>`).join('')}</div><button id="advance" class="primary advance" ${state.ended?'disabled':''}>${ACTIVITIES[activity].name} · 推进${speed===1?'一天':speed===7?'一周':speed===30?'一月':'一年'} →</button><p class="sub">快进将沿用此活动，每天结算；最迟在下一年度抉择前停下。</p></div></section>`}<div class="section card"><div class="section-head"><h3>人生手记</h3><span class="sub">最近的足迹</span></div><div class="timeline">${state.logs.length?state.logs.map(l=>`<div class="log"><time>${Math.floor(l.day/365)}岁 · 第${l.day%365}天</time>${esc(l.text)}</div>`).join(''):'<p class="sub">你出生在澄川的一个平凡清晨。故事从今天开始。</p>'}</div></div></section><aside class="right"><section class="card"><span class="eyebrow">THE LONG ROAD</span><h3>青云阶梯</h3><p class="sub">职级逐阶 · 职务另计</p><div class="rank-list">${RANKS.map((r,i)=>`<div class="rank ${r===c.rank?'active':''}">${String(i+1).padStart(2,'0')}　${r}${r===c.rank?' ←':''}</div>`).join('')}</div><div class="divider"></div><p class="sub">国家之巅</p><h3 class="gold">国家主席</h3><p class="sub">完美决策目标：${Math.floor(state.lifespan*.8)}岁<br>领导职务进程 ${Math.floor(c.progress*100)}%</p><div class="bar"><i style="width:${c.progress*100}%"></i></div><button id="offices" class="smallbtn" style="margin-top:15px">查看完整职务序列 ↗</button></section><section class="card section"><span class="eyebrow">GIFT OF DESTINY</span><h3>♫ 闻弦知意</h3><p class="sub">当重要的选择出现，试听每个选项的旋律。明亮与低沉之中，藏着方向。</p><span class="badge">已装备 · BGM 金手指</span></section></aside></div>`;
$('#export').onclick=exportSave;$('#import').onclick=importSave;$('#reset').onclick=()=>{modal('<h2>开启新的人生</h2><p>先导出当前存档，以便以后继续。</p><button id="backup">导出当前存档</button> <button id="new-life">确认开启新人生</button>');$('#backup').onclick=exportSave;$('#new-life').onclick=()=>{state=null;allocation=[20,20,20,20,20];try{localStorage.removeItem(STORAGE);}catch{}$('#modal').close();setup();};};$('#offices').onclick=()=>modal('<h2>领导职务序列</h2>'+OFFICES.slice(1).map((x,i)=>`<div class="rank">${i+1}　${x}</div>`).join('')+'<p class="sub">职务、职级、数字级别为三套展示。此处晋升为虚构规则。</p>');
document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>{activity=+b.dataset.activity;render();});document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=+b.dataset.speed;render();});if($('#advance'))$('#advance').onclick=()=>{const before=career(state).office;advance(state,speed,activity);save();render();const after=career(state).office;if(after!==before)toast('新的人生篇章：'+after);};document.querySelectorAll('[data-listen]').forEach(b=>b.onclick=async()=>{try{await playHint(+b.dataset.listen===e.answer);toast('旋律正在播放 · 请聆听情绪');}catch{toast('当前浏览器未能播放声音，请重试或更换浏览器。');}});document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{stop();const result=decide(state,+b.dataset.choice);save();render();modal(`<span class="eyebrow">ANNUAL REVIEW · ${result.age}</span><h2>${result.ok?'方向正确，向上一步。':'走过弯路，也留下思考。'}</h2><p>${esc(result.choice)}</p><p>${esc(result.report)}</p><p class="gold">履历 +${result.ok?100:20}${result.ok?' · 五维各 +0.5':''}</p>`);});if($('#stop'))$('#stop').onclick=stop;}
function exportSave(){if(!state)return;const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='qingyun-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file||file.size>2000000)throw Error('存档文件过大');const next=validate(JSON.parse(await file.text()));state=next;save();render();toast('存档已载入');}catch{toast('导入失败：请使用有效的青云纪存档。');}};input.click();}
render();
